import{_ as o,o as t,c as a,a3 as r}from"./chunks/framework.DACwFHq9.js";const p=JSON.parse('{"title":"Workspace Management","description":"Learn how to manage workspaces, notes, folders, and navigate the dashboard in Notely.","frontmatter":{"title":"Workspace Management","description":"Learn how to manage workspaces, notes, folders, and navigate the dashboard in Notely.","keywords":"workspace, landing screen, folders, sidebar, dashboard, favorites, continue writing","category":"Workspace"},"headers":[],"relativePath":"workspace/index.md","filePath":"workspace/index.md","lastUpdated":1789752683000}'),n={name:"workspace/index.md"};function s(i,e,l,d,c,g){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="workspace-overview" tabindex="-1">Workspace Overview <a class="header-anchor" href="#workspace-overview" aria-label="Permalink to &quot;Workspace Overview&quot;">​</a></h1><p>A workspace is the single source of truth for your notes in Notely. It maps to a folder on your local filesystem containing Markdown documents and asset subfolders.</p><h2 id="_1-landing-dashboard" tabindex="-1">1. Landing Dashboard <a class="header-anchor" href="#_1-landing-dashboard" aria-label="Permalink to &quot;1. Landing Dashboard&quot;">​</a></h2><p>When you open a workspace, you are greeted by the landing dashboard, which provides quick access to recent work and workspace health:</p><ul><li><strong>Continue Writing</strong>: Shows the single most recently edited note to resume editing instantly.</li><li><strong>Recent Notes</strong>: Displays a chronological list of recent notes.</li><li><strong>Favorites</strong>: Starred notes for immediate access.</li><li><strong>Open Tasks</strong>: Summarizes unchecked tasks across the workspace.</li></ul><hr><h2 id="_2-note-and-folder-creation" tabindex="-1">2. Note and Folder Creation <a class="header-anchor" href="#_2-note-and-folder-creation" aria-label="Permalink to &quot;2. Note and Folder Creation&quot;">​</a></h2><ul><li><strong>New Note</strong>: Create notes from <strong>File → New Note</strong> (<code>Ctrl + N</code>).</li><li><strong>New Folder</strong>: Create subfolders inside the sidebar list view to group notes logically.</li><li><strong>Rename &amp; Delete</strong>: Available from the note context menu. Deleted files are safely moved to the &quot;Removed&quot; folder pool managed by Notely.</li><li><strong>Drag &amp; Drop to Folder</strong>: Drag any note card, table row, or tree node directly into a folder to move it immediately. <ul><li><strong>Spring-Loading</strong>: Hovering a dragged note over a collapsed folder for 600ms automatically expands the folder.</li><li><strong>Breadcrumb Navigation Drop</strong>: Drag notes onto any ancestor folder in the breadcrumb path to move them up the directory tree.</li><li><strong>Drop Between Files</strong>: In Tree View, dropping onto or between files displays an accent insertion line and moves the note into that containing folder.</li></ul></li><li><strong>Recycle Bin Panel</strong>: Drag notes directly to the Recycle Bin panel at the bottom of the dashboard rail. A confirmation prompt confirms the action before moving the note to <code>.notes-app/removed/notes/</code>, with 1-click <strong>Undo</strong> toast support.</li></ul><hr><h2 id="_3-density-layout-views" tabindex="-1">3. Density &amp; Layout Views <a class="header-anchor" href="#_3-density-layout-views" aria-label="Permalink to &quot;3. Density &amp; Layout Views&quot;">​</a></h2><p>Customize how you browse your workspace contents:</p><ul><li><strong>Tile View</strong> (<code>Ctrl/Cmd + 1</code>): Card-style layout showing note content previews and media thumbnails.</li><li><strong>Table View</strong> (<code>Ctrl/Cmd + 2</code>): Compact, grid-based list view for scanning large note lists quickly. Double-click any note row in Table View to open it immediately.</li><li><strong>Tree View</strong> (<code>Ctrl/Cmd + 3</code>): Hierarchical tree layout displaying nested subfolders and notes with expandable/collapsible nodes, custom icon badges, color accents, and modification dates.</li><li><strong>Comfortable Density</strong> (<code>Ctrl/Cmd + 4</code>): Added margins and breathing room.</li><li><strong>Compact Density</strong> (<code>Ctrl/Cmd + 5</code>): High-density display for reviewing many documents at once.</li></ul><hr><h2 id="_4-workspace-tools-embedded-terminal" tabindex="-1">4. Workspace Tools &amp; Embedded Terminal <a class="header-anchor" href="#_4-workspace-tools-embedded-terminal" aria-label="Permalink to &quot;4. Workspace Tools &amp; Embedded Terminal&quot;">​</a></h2><p>Notely includes integrated workspace utilities for project productivity:</p><ul><li><strong><a href="/workspace/tasks.html">Tasks &amp; Checklists</a></strong>: Workspace-wide task tracking with bi-directional markdown sync.</li><li><strong><a href="/workspace/calendar.html">Calendar &amp; Scheduling</a></strong>: Visual timeline, due dates, and hourly schedule grid.</li><li><strong><a href="/workspace/graph.html">Knowledge Graph</a></strong>: Interactive entity and relationship visualization.</li><li><strong><a href="/workspace/terminal.html">Embedded Terminal</a></strong>: Project-local command execution with PTY process control and security policies.</li></ul><hr><h2 id="_5-workspace-document-reloading" tabindex="-1">5. Workspace &amp; Document Reloading <a class="header-anchor" href="#_5-workspace-document-reloading" aria-label="Permalink to &quot;5. Workspace &amp; Document Reloading&quot;">​</a></h2><p>Keep your workspace and active notes synchronized with external changes on disk:</p><ul><li><strong>Reload Workspace</strong>: Click the <strong>Reload</strong> button in the landing list controls, select <strong>Workspace → Reload Workspace</strong> (<code>Ctrl + Alt + R</code>), or run <strong>Reload Workspace from Disk</strong> in the Command Palette to re-scan all workspace documents, folder structures, open note tabs, and git status.</li><li><strong>External Change Banner &amp; Reload Note</strong>: When an active note is modified externally by another tool or process, Notely detects the change, temporarily disables autosave to prevent overwriting disk state, and displays a warning banner. Click <strong>Reload content from disk</strong>, select <strong>File → Reload Note from Disk</strong> (<code>Ctrl + Shift + R</code>), right-click the note tab and choose <strong>Reload from Disk</strong>, or use the Command Palette to force-load the latest file content from disk.</li></ul>',20)])])}const m=o(n,[["render",s]]);export{p as __pageData,m as default};
